## 1. Источник воды как нормальная сущность

Файл (пример): `rps/world/environment/water-source.entity.ts`

```ts
import type { HexId } from '../hex.entity';
import type { ActorEntity } from '../actor/actor.entity';

/**
 * Источник воды в конкретном гексе:
 * лужа, родник, колодец, кусок реки и т.п.
 */
export class WaterSourceEntity {
	private id: string;
	private hexId: HexId;
	private liters: number;
	private maxLiters: number;
	private regenRatePerHour: number; // литров/час (0 — не восстанавливается)

	constructor(params: {
		id: string;
		hexId: HexId;
		liters: number;
		maxLiters?: number;
		regenRatePerHour?: number;
	}) {
		this
			.setId(params.id)
			.setHexId(params.hexId)
			.setMaxLiters(params.maxLiters ?? params.liters)
			.setLiters(params.liters)
			.setRegenRatePerHour(params.regenRatePerHour ?? 0);
	}

	setId(id: string): this {
		this.id = id;
		return this;
	}

	getId(): string {
		return this.id;
	}

	setHexId(hexId: HexId): this {
		this.hexId = hexId;
		return this;
	}

	getHexId(): HexId {
		return this.hexId;
	}

	setLiters(liters: number): this {
		this.liters = Math.min(this.maxLiters, Math.max(0, liters));
		return this;
	}

	getLiters(): number {
		return this.liters;
	}

	changeLiters(delta: number): this {
		return this.setLiters(this.liters + delta);
	}

	setMaxLiters(maxLiters: number): this {
		this.maxLiters = Math.max(0, maxLiters);
		return this;
	}

	getMaxLiters(): number {
		return this.maxLiters;
	}

	setRegenRatePerHour(rate: number): this {
		this.regenRatePerHour = Math.max(0, rate);
		return this;
	}

	getRegenRatePerHour(): number {
		return this.regenRatePerHour;
	}

	/**
	 * Восстановление воды со временем (например, родник).
	 */
	regenerate(deltaHours: number): void {
		if (this.regenRatePerHour <= 0) return;
		this.changeLiters(this.regenRatePerHour * deltaHours);
	}

	/**
	 * Сколько воды этот источник готов отдать конкретному актору сейчас.
	 * По умолчанию — весь доступный объём.
	 */
	getDrinkableWaterLitersFor(_actor: ActorEntity): number {
		return this.liters;
	}

	/**
	 * Списать часть воды из источника.
	 */
	consumeDrinkableWater(_actor: ActorEntity, liters: number): void {
		if (liters <= 0) return;
		this.liters = Math.max(0, this.liters - liters);
	}
}
```

Никаких изменений в `WorldState`/`HexContentInstance` тут нет — просто новая сущность.

