## 2. Нормальная сущность локации “Ящерица и лужа”

Файл: `rps/world/locations/lizard-puddle.location.entity.ts`  
(папку `locations` можно завести именно под такие штуки)

```ts
import {
	HexCoord,
	HexEntity,
	HexId,
	makeHexId,
	VolumeUnits,
} from '../hex.entity';
import type { WorldState } from '../world-state';
import type { ActorEntity } from '../actor/actor.entity';
import { LIZARD_PROFILE } from '../creatures/lizard.profile';
import { WaterSourceEntity } from '../environment/water-source.entity';

export interface LizardPuddleLocationInit {
	id?: string;
	name?: string;
	radius?: number;
	lizardCoord?: HexCoord;
	puddleCoord?: HexCoord;
	puddleLiters?: number;
}

/**
 * Конкретная тестовая локация:
 *  - диск гексов радиусом N (по axial);
 *  - ящерица в одной точке;
 *  - лужа воды в другой.
 *
 * Работает поверх WorldState, но не меняет его форму.
 */
export class LizardPuddleLocationEntity {
	private id: string;
	private name: string;

	private radius: number;

	private world: WorldState;

	private lizardId: string | null = null;
	private lizardHexId: HexId | null = null;

	private puddleSourceId: string | null = null;
	private puddleHexId: HexId | null = null;

	private waterSourcesById: Record<string, WaterSourceEntity> = {};

	constructor(params: LizardPuddleLocationInit = {}) {
		this
			.setId(params.id ?? 'location:lizard-puddle')
			.setName(params.name ?? 'Lizard & Puddle Test Location')
			.setRadius(params.radius ?? 10);

		this.world = {
			hexes: {},
			contents: {},
			itemTypes: {},
			itemInstances: {},
			creatures: {},
		};

		this.buildHexDisc();

		this.addLizard(params.lizardCoord ?? { q: 3, r: -2 });
		this.addPuddle(
			params.puddleCoord ?? { q: -4, r: 6 },
			params.puddleLiters ?? 10,
		);
	}

	// ────────────────────────────────────────────────────────────
	// Базовые сеттеры / геттеры
	// ────────────────────────────────────────────────────────────

	setId(id: string): this {
		this.id = id;
		return this;
	}

	getId(): string {
		return this.id;
	}

	setName(name: string): this {
		this.name = name;
		return this;
	}

	getName(): string {
		return this.name;
	}

	setRadius(radius: number): this {
		this.radius = Math.max(1, radius);
		return this;
	}

	getRadius(): number {
		return this.radius;
	}

	getWorld(): WorldState {
		return this.world;
	}

	// ────────────────────────────────────────────────────────────
	// Построение диска гексов
	// ────────────────────────────────────────────────────────────

	private buildHexDisc(): void {
		const radius = this.radius;
		const hexes = this.world.hexes;

		for (let q = -radius; q <= radius; q++) {
			for (let r = -radius; r <= radius; r++) {
				const coord: HexCoord = { q, r };
				const s = -q - r;
				const dist = (Math.abs(q) + Math.abs(r) + Math.abs(s)) / 2;
				if (dist <= radius) {
					const hex = new HexEntity({ coord });
					hexes[hex.id] = hex;
				}
			}
		}
	}

	// ────────────────────────────────────────────────────────────
	// Ящерица
	// ────────────────────────────────────────────────────────────

	private addLizard(coord: HexCoord): void {
		const hexId: HexId = makeHexId(coord);
		const hexes = this.world.hexes;

		if (!hexes[hexId]) {
			hexes[hexId] = new HexEntity({ coord });
		}

		const lizardId = 'creature:lizard#1';
		const lizardName = 'Lizard';

		const lizard = LIZARD_PROFILE.createActor(hexId, lizardId, lizardName);

		this.world.creatures[lizardId] = lizard;

		const contentId = 'content:lizard#1';
		const volume: VolumeUnits = lizard.physical?.baseVolume ?? 0.5;

		this.world.contents[contentId] = {
			id: contentId,
			kind: 'creature',
			hexId,
			volume,
			creatureId: lizardId,
		};

		this.world.hexes[hexId].addContentId(contentId);

		this.lizardId = lizardId;
		this.lizardHexId = hexId;
	}

	getLizardId(): string | null {
		return this.lizardId;
	}

	getLizard(): ActorEntity | null {
		if (!this.lizardId) return null;
		return this.world.creatures[this.lizardId] ?? null;
	}

	getLizardHexId(): HexId | null {
		return this.lizardHexId;
	}

	// ────────────────────────────────────────────────────────────
	// Лужа (источник воды)
	// ────────────────────────────────────────────────────────────

	private addPuddle(coord: HexCoord, liters: number): void {
		const hexId: HexId = makeHexId(coord);
		const hexes = this.world.hexes;

		if (!hexes[hexId]) {
			hexes[hexId] = new HexEntity({ coord });
		}

		const puddleSourceId = 'waterSource:puddle#1';

		const puddleSource = new WaterSourceEntity({
			id: puddleSourceId,
			hexId,
			liters,
			maxLiters: liters,
			regenRatePerHour: 0,
		});

		this.waterSourcesById[puddleSourceId] = puddleSource;

		// Если хочешь, можно зарегистрировать лужу как "structure" в contents,
		// чтобы общий мир знал, что в гексе есть что-то стационарное.
		const contentId = 'content:puddle#1';

		this.world.contents[contentId] = {
			id: contentId,
			kind: 'structure',
			hexId,
			volume: 0,
			structureId: puddleSourceId,
		};

		this.world.hexes[hexId].addContentId(contentId);

		this.puddleSourceId = puddleSourceId;
		this.puddleHexId = hexId;
	}

	getPuddleHexId(): HexId | null {
		return this.puddleHexId;
	}

	getPuddleSource(): WaterSourceEntity | null {
		if (!this.puddleSourceId) return null;
		return this.waterSourcesById[this.puddleSourceId] ?? null;
	}

	getWaterSourcesInHex(hexId: HexId): WaterSourceEntity[] {
		return Object.values(this.waterSourcesById).filter(
			(source) => source.getHexId() === hexId,
		);
	}

	// ────────────────────────────────────────────────────────────
	// Утилиты для симуляции
	// ────────────────────────────────────────────────────────────

	/**
	 * Простая "прокрутка времени":
	 * обновляем все источники воды в локации.
	 */
	tick(deltaTimeMs: number): void {
		const deltaHours = deltaTimeMs / (1000 * 60 * 60);
		if (deltaHours <= 0) return;

		for (const source of Object.values(this.waterSourcesById)) {
			source.regenerate(deltaHours);
		}
	}

	/**
	 * Простейший хелпер: получить гекс по координате.
	 */
	getHexByCoord(coord: HexCoord): HexEntity | null {
		const id = makeHexId(coord);
		return this.world.hexes[id] ?? null;
	}

	/**
	 * Хелпер: получить гекс по id.
	 */
	getHexById(hexId: HexId): HexEntity | null {
		return this.world.hexes[hexId] ?? null;
	}
}
```

Ключевые моменты:

- Это **нормальная сущность** с конструктором и сеттерами, а не “фабричная функция-кадавр”.
- Она **инкапсулирует `WorldState`**, но не меняет его интерфейс.
- Вода — это `WaterSourceEntity`, живущая в отдельном реестре `waterSourcesById`.
- Привязка к гексу делается:
  - через `hexId` внутри `WaterSourceEntity`,
  - и опционально через `contents` (`kind: 'structure'`, `structureId`), чтобы мир мог знать, что в гексе есть некий стационарный объект.

---

## 3. Как этим пользоваться

Пример:

```ts
import { LizardPuddleLocationEntity } from 'rps/world/locations/lizard-puddle.location.entity';

const location = new LizardPuddleLocationEntity();

const world = location.getWorld();
const lizard = location.getLizard();
const puddle = location.getPuddleSource();

if (lizard && puddle) {
	const lizardHexId = location.getLizardHexId();
	const puddleHexId = location.getPuddleHexId();

	// расстояние между гексами, навигация и т.п. — через существующие хелперы мира
}
```

Когда дойдём до интеграции с DRINK / ActionContext, у нас уже будет:

- объект локации, знающий, где вода;
- методы `getWaterSourcesInHex(hexId)`, `tick(deltaTimeMs)` и т.п.;
- `WorldState`, compatible с существующим кодом.

И уже **поверх этого** можно будет аккуратно переписать `drinkFromWorld` так, чтобы он работал не с "магическими" методами гекса, а с `LocationEntity`, но не через `as any`.

Если хочешь, следующим шагом могу:

- показать аккуратный вариант `drinkFromWorld(actor, location, requestedLiters)`, который использует `getWaterSourcesInHex` и не трогает форму `ActionContext`;  
- или добавить в `LizardPuddleLocationEntity` метод `createActionContextForLizardAtPuddle()`, чтобы можно было сразу кормить его в DRINK.

