## 2. Универсальная сущность локации

**Файл:** `rps/world/locations/location.entity.ts` (новая папка `locations` внутри `world`).

```ts
// world/locations/location.entity.ts
// Универсальная сущность "локации" поверх WorldState.

import {
	HexCoord,
	HexEntity,
	HexId,
	makeHexId,
	VolumeUnits,
} from '../hex.entity';
import type { WorldState } from '../world-state';
import type { ActorEntity } from '../actor/actor.entity';
import { WaterSourceEntity, WaterSourceInit } from '../environment/water-source.entity';

export interface LocationEntityInit {
	id?: string;
	name?: string;

	/** Можно подсунуть уже собранный мир; по умолчанию создаётся пустой. */
	world?: WorldState;
}

/**
 * Локация:
 *  - держит внутри WorldState (гексы, contents, предметы, акторы);
 *  - знает про свои "окруженческие" сущности (например, источники воды);
 *  - даёт удобные хелперы для построения и тика.
 *
 * Без тупых геттеров: основные поля публичные, для конфигурации — сеттеры и методы.
 */
export class LocationEntity {
	id: string;
	name: string;

	world: WorldState;

	/** Реестр источников воды в этой локации. */
	waterSources: Record<string, WaterSourceEntity> = {};

	constructor(init: LocationEntityInit = {}) {
		this.id = init.id ?? '';
		this.name = init.name ?? '';

		this.world = init.world ?? {
			hexes: {},
			contents: {},
			itemTypes: {},
			itemInstances: {},
			creatures: {},
		};
	}

	setId(id: string): this {
		this.id = id;
		return this;
	}

	setName(name: string): this {
		this.name = name;
		return this;
	}

	setWorld(world: WorldState): this {
		this.world = world;
		return this;
	}

	// ─────────────────────────────────────────────────────
	// Гексы
	// ─────────────────────────────────────────────────────

	/** Зарегистрировать готовый гекс. Если id совпадает — перезаписываем. */
	registerHex(hex: HexEntity): this {
		this.world.hexes[hex.id] = hex;
		return this;
	}

	/** Убедиться, что гекс с такими координатами существует, и вернуть его. */
	ensureHex(coord: HexCoord): HexEntity {
		const id = makeHexId(coord);
		const existing = this.world.hexes[id];
		if (existing) return existing;

		const hex = new HexEntity({ coord, id });
		this.world.hexes[hex.id] = hex;
		return hex;
	}

	/** Заполнить локацию диском гексов вокруг (0;0) радиусом radius. */
	fillHexDiscAroundOrigin(radius: number): this {
		const r = Math.max(0, Math.floor(radius));

		for (let q = -r; q <= r; q++) {
			for (let s = -r; s <= r; s++) {
				const rCoord = -q - s;
				const dist = (Math.abs(q) + Math.abs(rCoord) + Math.abs(s)) / 2;
				if (dist <= r) {
					const coord: HexCoord = { q, r: rCoord };
					this.ensureHex(coord);
				}
			}
		}

		return this;
	}

	// ─────────────────────────────────────────────────────
	// Акторы
	// ─────────────────────────────────────────────────────

	/**
	 * Разместить актора в гексе и создать для него HexContentInstance.
	 *
	 * contentId можно не передавать — тогда будет сгенерирован примитивный id.
	 */
	placeCreature(params: {
		actor: ActorEntity;
		hexId: HexId;
		contentId?: string;
		volume?: VolumeUnits;
	}): this {
		const { actor, hexId } = params;
		const contentId = params.contentId ?? `content:creature:${actor.id}`;
		const volume: VolumeUnits = params.volume ?? actor.physical?.baseVolume ?? 1;

		// регистрируем актора
		this.world.creatures[actor.id] = actor;

		// убеждаемся, что гекс есть
		const hex = this.world.hexes[hexId] ?? new HexEntity({ coord: this.parseHexId(hexId), id: hexId });
		this.world.hexes[hex.id] = hex;

		// создаём контент
		this.world.contents[contentId] = {
			id: contentId,
			kind: 'creature',
			hexId,
			volume,
			creatureId: actor.id,
		};

		hex.addContentId(contentId);

		// синхронизируем hexId актора
		actor.hexId = hexId;

		return this;
	}

	/** Примитивный парсер "q;r" обратно в HexCoord, если надо. */
	private parseHexId(id: HexId): HexCoord {
		const [qStr, rStr] = String(id).split(';');
		const q = Number(qStr ?? 0) || 0;
		const r = Number(rStr ?? 0) || 0;
		return { q, r };
	}

	// ─────────────────────────────────────────────────────
	// Источники воды
	// ─────────────────────────────────────────────────────

	/**
	 * Добавить источник воды в локацию.
	 *
	 * По умолчанию создаёт для него "structure"-контент с нулевым объёмом,
	 * чтобы система объёма гекса о нём знала.
	 */
	addWaterSource(params: WaterSourceInit & {
		contentId?: string;
		volume?: VolumeUnits;
		registerContent?: boolean;
	}): WaterSourceEntity {
		const {
			contentId = `content:water:${params.id}`,
			volume = 0,
			registerContent = true,
			...sourceInit
		} = params;

		// убеждаемся, что гекс существует
		const hex = this.world.hexes[sourceInit.hexId];
		if (!hex) {
			// если гекс не был создан — создаём с координатами из id
			const coord = this.parseHexId(sourceInit.hexId);
			this.ensureHex(coord);
		}

		const source = new WaterSourceEntity(sourceInit);
		this.waterSources[source.id] = source;

		if (registerContent) {
			this.world.contents[contentId] = {
				id: contentId,
				kind: 'structure',
				hexId: source.hexId,
				volume,
				structureId: source.id,
			};
			this.world.hexes[source.hexId].addContentId(contentId);
		}

		return source;
	}

	/** Найти все источники воды, привязанные к конкретному гексу. */
	findWaterSourcesInHex(hexId: HexId): WaterSourceEntity[] {
		const result: WaterSourceEntity[] = [];
		for (const source of Object.values(this.waterSources)) {
			if (source.hexId === hexId) {
				result.push(source);
			}
		}
		return result;
	}

	// ─────────────────────────────────────────────────────
	// Тик окружения
	// ─────────────────────────────────────────────────────

	/** Прокрутка времени для окружения (пока — только вода). */
	tick(deltaTimeMs: number): void {
		if (!Number.isFinite(deltaTimeMs) || deltaTimeMs <= 0) return;
		const deltaHours = deltaTimeMs / (1000 * 60 * 60);

		for (const source of Object.values(this.waterSources)) {
			source.regenerate(deltaHours);
		}
	}
}
```

