## 2. Вода как отдельные сущности + хелперы

### 2.1. `WaterSourceEntity` (оставляем как есть)

Файл: `rps/world/environment/water-source.entity.ts`

```ts
// world/environment/water-source.entity.ts

import type { HexId } from '../hex.entity';
import type { ActorEntity } from '../actor/actor.entity';

export interface WaterSourceInit {
	id: string;
	hexId: HexId;
	liters: number;
	maxLiters?: number;
	regenRatePerHour?: number;
}

export class WaterSourceEntity {
	id: string;
	hexId: HexId;

	liters: number;
	maxLiters: number;
	regenRatePerHour: number;

	constructor(params: WaterSourceInit) {
		this
			.setId(params.id)
			.setHexId(params.hexId)
			.setMaxLiters(params.maxLiters ?? params.liters)
			.setLiters(params.liters)
			.setRegenRatePerHour(params.regenRatePerHour ?? 0);
	}

	setId(id: string): this {
		this.id = id;
		return this;
	}

	setHexId(hexId: HexId): this {
		this.hexId = hexId;
		return this;
	}

	setLiters(liters: number): this {
		const v = Number.isFinite(liters) ? liters : 0;
		this.liters = Math.min(this.maxLiters, Math.max(0, v));
		return this;
	}

	changeLiters(delta: number): this {
		return this.setLiters(this.liters + delta);
	}

	setMaxLiters(maxLiters: number): this {
		const v = Number.isFinite(maxLiters) ? maxLiters : 0;
		this.maxLiters = Math.max(0, v);
		if (this.liters > this.maxLiters) {
			this.liters = this.maxLiters;
		}
		return this;
	}

	setRegenRatePerHour(rate: number): this {
		const v = Number.isFinite(rate) ? rate : 0;
		this.regenRatePerHour = Math.max(0, v);
		return this;
	}

	regenerate(deltaHours: number): void {
		if (this.regenRatePerHour <= 0 || deltaHours <= 0) return;
		this.changeLiters(this.regenRatePerHour * deltaHours);
	}

	getDrinkableWaterLitersFor(_actor: ActorEntity): number {
		return this.liters;
	}

	consumeDrinkableWater(_actor: ActorEntity, liters: number): void {
		if (!Number.isFinite(liters) || liters <= 0) return;
		const take = Math.min(this.liters, liters);
		if (take <= 0) return;
		this.liters -= take;
	}
}
```

### 2.2. Хелперы для воды в локации

**Новый файл:** `rps/world/environment/location-water.helpers.ts`  
(всё, что раньше торчало методами из `LocationEntity`, уезжает сюда).

```ts
// world/environment/location-water.helpers.ts

import type { VolumeUnits, HexId, HexCoord } from '../hex.entity';
import { HexEntity, makeHexId } from '../hex.entity';
import type { WorldState } from '../world-state';
import { LocationEntity } from '../locations/location.entity';
import { WaterSourceEntity, WaterSourceInit } from './water-source.entity';

export interface LocationWaterState {
	waterSources: Record<string, WaterSourceEntity>;
}

/** Создать пустое состояние воды для локации. */
export function createEmptyLocationWaterState(): LocationWaterState {
	return { waterSources: {} };
}

/**
 * Добавить источник воды в world конкретной локации.
 * Локация остаётся универсальной — вода живёт в отдельной структуре.
 */
export function addWaterSourceToLocation(
	location: LocationEntity,
	waterState: LocationWaterState,
	params: WaterSourceInit & {
		contentId?: string;
		volume?: VolumeUnits;
		registerContent?: boolean;
	},
): WaterSourceEntity {
	const {
		contentId = `content:water:${params.id}`,
		volume = 0,
		registerContent = true,
		...sourceInit
	} = params;

	const world: WorldState = location.world;

	// убеждаемся, что гекс существует
	let hex = world.hexes[sourceInit.hexId];
	if (!hex) {
		// если гекс не был создан — создаём с координатами из id
		const coord = parseHexId(sourceInit.hexId);
		hex = new HexEntity({ coord, id: sourceInit.hexId });
		world.hexes[hex.id] = hex;
	}

	const source = new WaterSourceEntity(sourceInit);
	waterState.waterSources[source.id] = source;

	if (registerContent) {
		world.contents[contentId] = {
			id: contentId,
			kind: 'structure',
			hexId: source.hexId,
			volume,
			structureId: source.id,
		};
		world.hexes[source.hexId].addContentId(contentId);
	}

	return source;
}

/** Найти все источники воды, привязанные к конкретному гексу. */
export function findWaterSourcesInHex(
	waterState: LocationWaterState,
	hexId: HexId,
): WaterSourceEntity[] {
	const result: WaterSourceEntity[] = [];
	for (const source of Object.values(waterState.waterSources)) {
		if (source.hexId === hexId) {
			result.push(source);
		}
	}
	return result;
}

/** Тик для воды в локации (восстановление и т.п.). */
export function tickLocationWater(
	waterState: LocationWaterState,
	deltaTimeMs: number,
): void {
	if (!Number.isFinite(deltaTimeMs) || deltaTimeMs <= 0) return;
	const deltaHours = deltaTimeMs / (1000 * 60 * 60);

	for (const source of Object.values(waterState.waterSources)) {
		source.regenerate(deltaHours);
	}
}

// Примитивный парсер "q;r" → HexCoord
function parseHexId(id: HexId): HexCoord {
	const [qStr, rStr] = String(id).split(';');
	const q = Number(qStr ?? 0) || 0;
	const r = Number(rStr ?? 0) || 0;
	return { q, r };
}
```

Теперь:

- `LocationEntity` — чистый и универсальный.
- Вода живёт в отдельной `LocationWaterState`.
- Операции с водой — через чистые функции-хелперы.

