## 2. Токен акторов (ящерица)

### `res://scenes/rps-location/rps_actor_token.gd`

```gdscript
class_name RpsActorToken
extends Node2D

## ID актора в снапшоте (creatureId)
@export var actor_id: String = ""

## Спрайт-лист актора (Lizzard 1-6.png)
@export var texture: Texture2D

## Кол-во фреймов по горизонтали (для ящерицы = 6)
@export var hframes: int = 6

## Индекс фейсинга (0..hframes-1), по аналогии с кораблями
@export var facing_index: int = 0

@onready var sprite: Sprite2D = $Sprite2D

func _ready() -> void:
	if texture:
		sprite.texture = texture

	sprite.hframes = max(hframes, 1)
	sprite.vframes = 1
	sprite.centered = true
	sprite.frame = clamp(facing_index, 0, sprite.hframes - 1)
```

