## 4. Сокет локации

### `res://scenes/rps-location/rps_location_socket.gd`

Пример, максимально близкий к `SeaCombatSocket`, но с отдельным сигналом под локацию:

```gdscript
class_name RpsLocationSocket
extends Node

@export var websocket_url: String = "ws://localhost:3000/ws"

var socket: WebSocketPeer = WebSocketPeer.new()

signal location_loaded(snapshot: Dictionary)

func _ready() -> void:
	set_process(false)
	_connect()

func _connect() -> void:
	var err := socket.connect_to_url(websocket_url)
	if err != OK:
		push_error("RpsLocationSocket: connect error %s" % err)
		return
	set_process(true)

func send_message(obj: Object) -> void:
	var json := _serialize_message(obj)
	socket.send_text(json)

func _serialize_message(obj: Object) -> String:
	var excludes: Array[String] = ["RefCounted", "script"]
	var result: Dictionary = {}
	var payload: Dictionary = {}
	for p in obj.get_property_list():
		if p.name.find(".message.gd") != -1:
			result["message"] = p.name.trim_suffix(".gd")
		elif !excludes.has(p.name):
			payload[p.name] = obj[p.name]
	result["payload"] = payload
	return JSON.stringify(result)

func _process(_delta: float) -> void:
	socket.poll()
	var state := socket.get_ready_state()

	if state == WebSocketPeer.STATE_OPEN:
		while socket.get_available_packet_count() > 0:
			var packet := socket.get_packet()
			var text := packet.get_string_from_utf8()
			var parsed := JSON.parse_string(text)
			if typeof(parsed) != TYPE_DICTIONARY:
				continue
			var response: String = str(parsed.get("response", ""))
			if response == "load-location-snapshot.response":
				var payload = parsed.get("payload", {})
				emit_signal("location_loaded", payload)

	elif state == WebSocketPeer.STATE_CLOSED:
		var code := socket.get_close_code()
		print("RpsLocationSocket closed: %s" % code)
		set_process(false)
```

> Здесь **нет жёстко зашитых путей** к message/response — они подхватываются по имени свойства, как в `SeaCombatSocket`.

